(function(){
  const role=()=>String((typeof state!=='undefined'&&state?.profile?.rol)||'').trim().toUpperCase();
  const has=m=>{try{return typeof rymHasModule==='function'&&rymHasModule(m)}catch(_){return false}};
  const oldOpen=window.phase6OpenUnit;
  if(typeof oldOpen==='function'){
    window.phase6OpenUnit=function(r){oldOpen(r);const m=document.querySelector('#ca6UnitModal');if(!m||m.querySelector('.v74-control-edit'))return;const canColor=role()==='ADMIN_TOTAL'||has('control_auto.editar_color'),canCupo=role()==='ADMIN_TOTAL'||has('control_auto.editar_cupo');if(!canColor&&!canCupo)return;const anchor=m.querySelector('.ca6-ena-card'),box=document.createElement('section');box.className='v74-control-edit';box.innerHTML=`<h3>Editar Control de Auto</h3><div class="muted">Cambios auditados. eCarcheck sigue siendo la fuente oficial del color y ATTT/cupos la fuente de asignación de cupo.</div><div class="v74-edit-grid">${canColor?`<div class="field"><label>Color</label><input id="v74EditColor" value="${esc(r.color||'')}" placeholder="Color"></div>`:''}${canCupo?`<div class="field"><label>Cupo</label><input id="v74EditCupo" value="${esc(r.placa_comercial||'')}" placeholder="Ej. 8T12345 o Sin cupo"></div>`:''}</div><div class="v74-edit-actions">${canColor?'<button class="soft-btn" id="v74SaveColor">Guardar color</button>':''}${canCupo?'<button class="soft-btn" id="v74SaveCupo">Guardar cupo</button>':''}</div><div class="v74-edit-msg" id="v74EditMsg"></div>`;anchor?.parentNode.insertBefore(box,anchor);const msg=box.querySelector('#v74EditMsg');async function save(action,val,btn){if(!val&&action==='COLOR')return;btn.disabled=true;btn.textContent='Guardando...';try{const {data}=await req('/functions/v1/control-auto-editar',{method:'POST',body:JSON.stringify({action,unidad:r.unidad,valor:val})});if(!data?.ok)throw Error(data?.error||'No se pudo guardar');msg.innerHTML=`<div class="success">${action==='COLOR'?'Color':'Cupo'} actualizado y auditado.</div>`;setTimeout(()=>{m.style.display='none';document.querySelector('#ca6Go')?.click()},400)}catch(e){msg.innerHTML=`<div class="alert">${esc(e.message||e)}</div>`;btn.disabled=false;btn.textContent=action==='COLOR'?'Guardar color':'Guardar cupo'}}const bc=box.querySelector('#v74SaveColor');if(bc)bc.onclick=()=>save('COLOR',String(box.querySelector('#v74EditColor').value||'').trim(),bc);const bp=box.querySelector('#v74SaveCupo');if(bp)bp.onclick=()=>save('CUPO',String(box.querySelector('#v74EditCupo').value||'').trim(),bp)};
    try{phase6OpenUnit=window.phase6OpenUnit}catch(_){ }
  }
  window.rymPrefetchRevisados=function(){try{if(!(typeof rymHasModule==='function'&&rymHasModule('portal.revisados')))return;const key=String(state?.profile?.id||'')+'|'+String(state?.profile?.rol||'').trim().toUpperCase();if(!key||key==='|')return;const cur=window.__rymRevisadosPrefetch;if(cur&&cur.key===key&&(cur.promise||cur.data)&&Date.now()-(cur.at||Date.now())<120000)return;const holder={key,at:Date.now(),data:null,promise:null};holder.promise=req('/functions/v1/revisados-final',{method:'POST',body:'{}'}).then(r=>{if(r.data?.ok){holder.data=r.data;holder.at=Date.now();return r.data}throw Error(r.data?.error||'prefetch_failed')}).catch(()=>null).finally(()=>{holder.promise=null});window.__rymRevisadosPrefetch=holder}catch(_){}};
  const oldHome=window.v36PortalHome;if(typeof oldHome==='function'){window.v36PortalHome=function(){const r=oldHome.apply(this,arguments);setTimeout(()=>window.rymPrefetchRevisados?.(),250);return r};try{v36PortalHome=window.v36PortalHome}catch(_){}}
  document.addEventListener('DOMContentLoaded',()=>{document.querySelector('#v36PortalHomeBtn')?.remove()});
})();
